function admin_footer(): void {echo '</main><footer class="admin-footer">MI Tech Wireless · All order times shown in America/New_York.</footer></div></body></html>';}
function field(string $name,string $label,$value='',string $type='text',string $attrs=''): void {echo '<label for="'.e($name).'">'.e($label).'</label><input id="'.e($name).'" name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.$attrs.'>';}
function area(string $name,string $label,string $value='',int $rows=3): void {echo '<label for="'.e($name).'">'.e($label).'</label><textarea id="'.e($name).'" name="'.e($name).'" rows="'.$rows.'">'.e($value).'</textarea>';}
function checkbox(string $name,string $label,bool $checked): void {echo '<label class="check-label"><input type="checkbox" name="'.e($name).'" value="1" '.($checked?'checked':'').'><span>'.e($label).'</span></label>';}
function action_form(string $action,int $id,string $label,bool $danger=false): void {echo '<form class="inline-form" method="post" '.($danger?'data-confirm="Delete this unused record? This cannot be undone."':'').'>'.csrf().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'"><button class="button secondary small '.($danger?'danger-text':'').'">'.e($label).'</button></form>';}
function carrier_select($value='',string $name='carrier_id',bool $all=false): void {echo '<label for="'.e($name).'">Carrier</label><select id="'.e($name).'" name="'.e($name).'">';if($all)echo '<option value="">All carriers</option>';foreach(all('SELECT id,name FROM carriers ORDER BY sort_order,name') as $c)echo '<option value="'.$c['id'].'" '.((string)$value===(string)$c['id']?'selected':'').'>'.e($c['name']).'</option>';echo '</select>';}
function dashboard_view(): void {
    global $config;$mode=($_GET['mode']??'live')==='test'?'test':'live';$now=new DateTimeImmutable('now',new DateTimeZone($config['timezone']));
    echo '<div class="admin-toolbar"><p>Payment totals are separated by Stripe mode.</p><div class="segmented"><a class="'.($mode==='live'?'active':'').'" href="/admin?mode=live">Live orders</a><a class="'.($mode==='test'?'active':'').'" href="/admin?mode=test">Test orders</a></div></div>';
    if(request_checkout_enabled())echo '<div class="notice"><strong>Request checkout is enabled.</strong> Review contact details in <a href="/admin/requests">Checkout requests</a>. These requests are awaiting payment.</div>';
    elseif(!checkout_ready())echo '<div class="notice"><strong>Finish store setup.</strong> Configure Stripe and SMTP, verify your plans, then enable checkout in <a href="/admin/settings">Settings</a>.</div>';
    echo '<div class="metric-grid">';foreach(['Today'=>$now->setTime(0,0),'This week'=>$now->modify('monday this week')->setTime(0,0),'This month'=>$now->modify('first day of this month')->setTime(0,0)] as $label=>$start){$date=$start->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$r=one('SELECT COUNT(*) AS orders,COALESCE(SUM(IF(payment_status IN (?,?,?),amount_cents-refunded_cents,0)),0) AS revenue FROM orders WHERE stripe_mode=? AND created_at>=?',['paid','partially_refunded','refunded',$mode,$date]);echo '<div class="metric"><span>'.e($label).'</span><strong>'.money($r['revenue']).'</strong><small>'.$r['orders'].' orders · net captured revenue</small></div>';}
    $pending=query('SELECT COUNT(*) FROM orders WHERE stripe_mode=? AND payment_status=? AND recharge_status IN (?,?)',[$mode,'paid','processing','failed'])->fetchColumn();echo '<a class="metric highlight" href="/admin/orders?payment=paid&mode='.$mode.'"><span>Needs attention</span><strong>'.$pending.'</strong><small>Paid, awaiting successful recharge →</small></a></div>';
    echo '<section class="surface"><div class="panel-title"><h2>Latest orders</h2><a class="text-link" href="/admin/orders">All orders →</a></div>';order_table(all('SELECT * FROM orders WHERE stripe_mode=? ORDER BY id DESC LIMIT 10',[$mode]));echo '</section>';
    $unverified=query('SELECT COUNT(*) FROM plans WHERE verify_pricing=1')->fetchColumn();$emailFailed=query('SELECT COUNT(*) FROM email_queue WHERE status=? AND attempts>0',['pending'])->fetchColumn();echo '<div class="admin-quick"><a class="surface" href="/admin/plans"><h3>Review your catalog</h3><p>'.$unverified.' plans need pricing and eligibility verification.</p><span class="text-link">Manage plans →</span></a><a class="surface" href="/admin/emails"><h3>Check email delivery</h3><p>'.$emailFailed.' messages need delivery attention.</p><span class="text-link">View email queue →</span></a></div>';
}
function order_filter(): array {
    $where=['1=1'];$params=[];
    foreach(['carrier'=>'carrier_id','payment'=>'payment_status','status'=>'recharge_status','mode'=>'stripe_mode'] as $field=>$column){$v=is_string($_GET[$field]??null)?$_GET[$field]:'';if($v!==''){$where[]=$column.'=?';$params[]=$v;}}
    $search=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,254):'';if($search!==''){$where[]='(order_number LIKE ? OR email LIKE ? OR recharge_phone LIKE ? OR customer_name LIKE ?)';array_push($params,...array_fill(0,4,'%'.$search.'%'));}
    global $config;foreach(['from'=>'>=','to'=>'<'] as $key=>$op){$v=$_GET[$key]??'';if(is_string($v)&&preg_match('/^\d{4}-\d{2}-\d{2}$/D',$v)){$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$v,new DateTimeZone($config['timezone']));if($dt&&$dt->format('Y-m-d')===$v){if($key==='to')$dt=$dt->modify('+1 day');$where[]='created_at'.$op.'?';$params[]=$dt->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');}}}
    return [implode(' AND ',$where),$params];
}
function order_table(array $orders): void {
    if(!$orders){echo '<div class="empty-state"><h3>No orders to show.</h3><p>Orders will appear here when customers start checkout.</p></div>';return;}
    echo '<div class="table-wrap"><table><thead><tr><th>Order / date</th><th>Customer</th><th>Recharge</th><th>Amount / card</th><th>Payment</th><th>Fulfillment</th></tr></thead><tbody>';
    foreach($orders as $o)echo '<tr><td><a class="strong-link" href="/admin/order?id='.$o['id'].'">'.e($o['order_number']).'</a><small>'.e(when($o['created_at'])).'</small>'.($o['stripe_mode']==='test'?'<span class="test-label">TEST</span>':'').'</td><td>'.e($o['customer_name']).'<small>'.e($o['email']).'</small></td><td>'.e(format_phone($o['recharge_phone'])).'<small>'.e($o['carrier_name'].' · '.$o['plan_name']).'</small></td><td><strong>'.money($o['amount_cents']).'</strong><small>'.e($o['card_last4']?$o['card_brand'].' •••• '.$o['card_last4']:'No card charged').'</small></td><td>'.status_badge($o['payment_status']).'</td><td>'.status_badge($o['recharge_status']).'</td></tr>';
    echo '</tbody></table></div>';
}
function orders_view(): void {?>
<form class="surface filters" method="get" action="/admin/orders"><div><?php field('q','Search order, email, phone or customer',$_GET['q']??'');?></div><div><?php carrier_select($_GET['carrier']??'','carrier',true);?></div><div><label for="payment">Payment</label><select name="payment" id="payment"><option value="">All payments</option><?php foreach(['pending','paid','failed','partially_refunded','refunded'] as $s):?><option <?=($_GET['payment']??'')===$s?'selected':''?> value="<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></div><div><label for="status">Recharge</label><select name="status" id="status"><option value="">All statuses</option><?php foreach(['awaiting_payment','processing','recharged','failed','refunded'] as $s):?><option <?=($_GET['status']??'')===$s?'selected':''?> value="<?=$s?>"><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></div><div><?php field('from','From',$_GET['from']??'','date');?></div><div><?php field('to','Through',$_GET['to']??'','date');?></div><div><label for="mode">Stripe mode</label><select name="mode" id="mode"><option value="">All modes</option><option value="live" <?=($_GET['mode']??'')==='live'?'selected':''?>>Live</option><option value="test" <?=($_GET['mode']??'')==='test'?'selected':''?>>Test</option></select></div><div class="filter-buttons"><button class="button primary">Apply filters</button><a class="button secondary" href="/admin/orders">Reset</a></div></form>
<?php [$where,$params]=order_filter();$page=max(1,min(100000,(int)($_GET['page']??1)));$count=query('SELECT COUNT(*) FROM orders WHERE '.$where,$params)->fetchColumn();$orders=all('SELECT * FROM orders WHERE '.$where.' ORDER BY id DESC LIMIT 50 OFFSET '.(($page-1)*50),$params);echo '<section class="surface"><div class="panel-title"><h2>'.$count.' orders</h2><a class="button secondary small" href="/admin/export?'.e(http_build_query($_GET)).'">Export CSV</a></div>';order_table($orders);paginate($page,(int)$count);echo '</section>';
}
function paginate(int $page,int $count): void {if($count<=50)return;echo '<nav class="pagination" aria-label="Pagination">';foreach([$page-1=>'← Previous',$page+1=>'Next →'] as $p=>$label){if($p<1||($p-1)*50>=$count)continue;echo '<a class="button secondary small" href="?'.e(http_build_query(array_merge($_GET,['page'=>$p]))).'">'.$label.'</a>';}echo '<span>Page '.$page.' of '.ceil($count/50).'</span></nav>';}
function export_orders(): void {[$where,$params]=order_filter();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="mitech-orders-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Order ID','Customer','Email','Contact phone','Recharge phone','ZIP','Carrier','Plan','Amount USD','Card brand','Last four','Payment','Recharge','Mode','Created UTC']);$q=query('SELECT * FROM orders WHERE '.$where.' ORDER BY id DESC',$params);while($o=$q->fetch()){$values=[$o['order_number'],$o['customer_name'],$o['email'],$o['customer_phone'],$o['recharge_phone'],$o['zip'],$o['carrier_name'],$o['plan_name'],number_format($o['amount_cents']/100,2,'.',''),$o['card_brand'],$o['card_last4'],$o['payment_status'],$o['recharge_status'],$o['stripe_mode'],$o['created_at']];$values=array_map(fn($v)=>preg_match('/^[\s]*[=+@\-]/u',(string)$v)?"'".$v:$v,$values);fputcsv($out,$values);}fclose($out);}
function order_view(): void {
    $o=one('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)]);if(!$o){echo '<p>Order not found.</p>';return;}
    echo '<a class="back-link" href="/admin/orders">← Back to orders</a><div class="admin-detail-grid"><section class="surface"><div class="panel-title"><h2>'.e($o['order_number']).'</h2>'.status_badge($o['stripe_mode']).'</div>';
    require_once ROOT.'/includes/layout.php';order_details($o);echo '<h3>Customer & payment</h3><dl class="order-details">';foreach(['Customer'=>$o['customer_name'],'Email'=>$o['email'],'Contact phone'=>format_phone($o['customer_phone']),'Billing ZIP'=>$o['zip'],'Stripe PaymentIntent'=>$o['payment_id']?:'Not created','Card'=>$o['card_brand'].' '.($o['card_last4']?'•••• '.$o['card_last4']:''),'Refunded'=>money($o['refunded_cents'])] as $k=>$v)echo '<div><dt>'.e($k).'</dt><dd>'.e($v).'</dd></div>';echo '</dl><h3>Plan at time of purchase</h3><p>'.e($o['plan_description']).'</p></section><section class="surface"><h2>Fulfillment</h2>';
    if($o['payment_status']==='paid'){?><form method="post"><?=csrf()?><input type="hidden" name="action" value="order_update"><input type="hidden" name="id" value="<?=$o['id']?>"><label for="recharge_status">Recharge status</label><select name="recharge_status" id="recharge_status"><?php foreach(['processing'=>'Processing','recharged'=>'Recharged','failed'=>'Failed'] as $key=>$label):?><option value="<?=$key?>" <?=$o['recharge_status']===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select><?php area('notes','Internal notes (not sent to customer)',$o['notes'],5);?><p class="muted">Mark Recharged only after you complete the refill. A completion email is queued automatically.</p><button class="button primary">Save fulfillment</button></form><?php }else echo '<p>Fulfillment can be updated after payment is confirmed and before refund.</p><p>'.nl2br(e($o['notes'])).'</p>';
    if(in_array($o['payment_status'],['paid','partially_refunded'],true)){?><details class="refund-box"><summary>Refund this payment</summary><p>This submits the remaining refundable amount to Stripe. It does not reverse a refill already delivered by a carrier.</p><form method="post" data-confirm="Submit a full remaining refund to the original payment method?"><?=csrf()?><input type="hidden" name="action" value="refund"><input type="hidden" name="id" value="<?=$o['id']?>"><?php field('password','Confirm your admin password','','password','required autocomplete="current-password"');?><button class="button danger-button">Issue refund <?=money($o['amount_cents']-$o['refunded_cents'])?></button></form></details><?php }
    echo '</section></div><section class="surface"><h2>Status history</h2><ol class="timeline">';foreach(all('SELECT h.*,a.email AS admin_email FROM order_status_history h LEFT JOIN admins a ON a.id=h.admin_id WHERE order_id=? ORDER BY h.id DESC',[$o['id']]) as $h)echo '<li>'.status_badge($h['status']).'<div>'.e($h['message']).'<small>'.e(when($h['created_at'])).' · '.e($h['admin_email']?:'System').'</small></div></li>';echo '</ol></section>';
}
function carriers_view(): void {
    echo '<div class="admin-toolbar"><p>Enable, disable and order carriers in the public directory.</p><a class="button primary" href="/admin/carrier">+ Add carrier</a></div><div class="surface table-wrap"><table><thead><tr><th>Carrier</th><th>Visibility</th><th>Order</th><th>Plans</th><th>Actions</th></tr></thead><tbody>';
    foreach(all('SELECT c.*,(SELECT COUNT(*) FROM plans p WHERE p.carrier_id=c.id) AS plans FROM carriers c ORDER BY sort_order,name') as $c){echo '<tr><td>'.carrier_logo($c).'<small>/carriers/'.e($c['slug']).'</small></td><td>'.status_badge($c['active']?'active':'disabled').'</td><td>'.$c['sort_order'].'</td><td><a href="/admin/plans?carrier='.$c['id'].'">'.$c['plans'].' plans</a></td><td class="row-actions"><a class="button secondary small" href="/admin/carrier?id='.$c['id'].'">Edit</a>';action_form('carrier_toggle',(int)$c['id'],$c['active']?'Disable':'Enable');action_form('carrier_delete',(int)$c['id'],'Delete',true);echo '</td></tr>';}
    echo '</tbody></table></div>';
}
function carrier_view(): void {
    $id=(int)($_GET['id']??0);$c=$id?one('SELECT * FROM carriers WHERE id=?',[$id]):['id'=>'','name'=>'','slug'=>'','color'=>'#222222','description'=>'','number_hint'=>'Enter your existing 10-digit US prepaid mobile number.','source_url'=>'','active'=>1,'sort_order'=>0,'logo'=>''];if(!$c){echo '<p>Carrier not found.</p>';return;}
    echo '<form class="surface editor" method="post" enctype="multipart/form-data">'.csrf().'<input type="hidden" name="action" value="carrier_save"><input type="hidden" name="id" value="'.e($c['id']).'"><div class="form-grid"><div>';field('name','Carrier name',$c['name'],'text','required maxlength="100"');echo '</div><div>';field('slug','URL slug',$c['slug'],'text','required pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="100"');echo '</div></div>';area('description','Description',$c['description']);field('number_hint','Phone number help',$c['number_hint']);field('source_url','Official pricing / refill source URL',$c['source_url'],'url');echo '<div class="form-grid"><div>';field('color','Wordmark color',$c['color'],'color');echo '</div><div>';field('sort_order','Display order (lower first)',$c['sort_order'],'number','min="0" max="9999" required');echo '</div></div>';field('logo','Upload carrier logo (PNG, JPEG, WebP, max 2 MB)','','file','accept="image/png,image/jpeg,image/webp"');checkbox('active','Show carrier on website',(bool)$c['active']);echo '<div class="form-actions"><button class="button primary">Save carrier</button><a class="button secondary" href="/admin/carriers">Cancel</a></div></form>';
}
function plans_view(): void {
    $carrier=(int)($_GET['carrier']??0);$plans=all('SELECT p.*,c.name AS carrier_name FROM plans p JOIN carriers c ON c.id=p.carrier_id '.($carrier?'WHERE p.carrier_id=?':'').' ORDER BY c.sort_order,p.sort_order,p.price_cents',$carrier?[$carrier]:[]);
    echo '<div class="admin-toolbar"><form class="inline-filter" method="get"><div>';carrier_select($carrier,'carrier',true);echo '</div><button class="button secondary">Filter</button></form><a class="button primary" href="/admin/plan?carrier='.$carrier.'">+ Add plan</a></div><div class="notice">Starter prices are research references. Confirm refill access, exact price, taxes, eligibility and fulfillment before clearing “Verify pricing.”</div><div class="surface table-wrap"><table><thead><tr><th>Plan</th><th>Price</th><th>State</th><th>Order</th><th>Actions</th></tr></thead><tbody>';
    foreach($plans as $p){echo '<tr><td><strong>'.e($p['name']).'</strong><small>'.e($p['carrier_name']).'</small></td><td>'.money($p['price_cents']).'</td><td>'.status_badge($p['verify_pricing']?'verify_pricing':($p['active']?'active':'disabled')).(!$p['active']?'<small>Hidden from website</small>':'').'</td><td>'.$p['sort_order'].'</td><td class="row-actions"><a class="button secondary small" href="/admin/plan?id='.$p['id'].'">Edit</a>';action_form('plan_toggle',(int)$p['id'],$p['active']?'Disable':'Enable');action_form('plan_delete',(int)$p['id'],'Delete',true);echo '</td></tr>';}
    if(!$plans)echo '<tr><td colspan="5">No plans for this carrier. Add a confirmed refill option to get started.</td></tr>';echo '</tbody></table></div>';
}
function plan_view(): void {
    $id=(int)($_GET['id']??0);$p=$id?one('SELECT * FROM plans WHERE id=?',[$id]):['id'=>'','carrier_id'=>(int)($_GET['carrier']??0),'name'=>'','price_cents'=>0,'data_allowance'=>'','talk'=>'','texts'=>'','validity_days'=>30,'description'=>'','popular'=>0,'active'=>1,'verify_pricing'=>1,'sort_order'=>0];if(!$p){echo '<p>Plan not found.</p>';return;}
    echo '<form class="surface editor" method="post">'.csrf().'<input type="hidden" name="action" value="plan_save"><input type="hidden" name="id" value="'.e($p['id']).'">';carrier_select($p['carrier_id']);field('name','Plan / refill name',$p['name'],'text','required maxlength="150"');echo '<div class="form-grid"><div>';field('price','Price (USD)',number_format($p['price_cents']/100,2,'.',''),'number','required min="1" max="2000" step="0.01"');echo '</div><div>';field('validity_days','Validity days (0 = follows existing plan)',$p['validity_days'],'number','min="0" max="3650" required');echo '</div></div>';field('data_allowance','Data allowance',$p['data_allowance']);field('talk','Talk allowance',$p['talk']);field('texts','Text allowance',$p['texts']);area('description','Plan details and eligibility',$p['description']);field('sort_order','Display order (lower first)',$p['sort_order'],'number','min="0" max="9999" required');checkbox('popular','Feature this plan',(bool)$p['popular']);checkbox('active','Show this plan on website',(bool)$p['active']);checkbox('verify_pricing','Verify pricing — blocks purchase until cleared',(bool)$p['verify_pricing']);echo '<p class="muted">Only clear verification after confirming the refill amount, availability and compatibility with your fulfillment provider.</p><div class="form-actions"><button class="button primary">Save plan</button><a class="button secondary" href="/admin/plans">Cancel</a></div></form>';
}
function customers_view(): void {
    $q=is_string($_GET['q']??null)?mb_substr($_GET['q'],0,254):'';$page=max(1,(int)($_GET['page']??1));$args=['%'.$q.'%','%'.$q.'%'];$count=query('SELECT COUNT(*) FROM customers WHERE email LIKE ? OR name LIKE ?',$args)->fetchColumn();
    echo '<form class="surface inline-filter" method="get"><div>';field('q','Search customers',$q);echo '</div><button class="button primary">Search</button></form><div class="surface table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Joined</th></tr></thead><tbody>';
    foreach(all('SELECT c.*,(SELECT COUNT(*) FROM orders o WHERE o.customer_id=c.id) AS orders FROM customers c WHERE email LIKE ? OR name LIKE ? ORDER BY c.id DESC LIMIT 50 OFFSET '.(($page-1)*50),$args) as $c)echo '<tr><td><a class="strong-link" href="/admin/customer?id='.$c['id'].'">'.e($c['name']).'</a><small>'.e($c['email']).'</small></td><td>'.e(format_phone($c['phone'])).'</td><td>'.$c['orders'].'</td><td>'.e(when($c['created_at'])).'</td></tr>';if(!$count)echo '<tr><td colspan="4">No customers yet.</td></tr>';echo '</tbody></table>';paginate($page,(int)$count);echo '</div>';
}
function customer_view(): void {$id=(int)($_GET['id']??0);$c=one('SELECT * FROM customers WHERE id=?',[$id]);if(!$c){echo '<p>Customer not found.</p>';return;}echo '<section class="surface"><h2>'.e($c['name']).'</h2><p>'.e($c['email']).' · '.e(format_phone($c['phone'])).'</p>';order_table(all('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC',[$id]));echo '</section>';}
function password_view(): void {echo '<form class="surface editor" method="post">'.csrf().'<input type="hidden" name="action" value="password"><p>Use at least 14 characters. A long, unique passphrase is a good choice.</p>';field('current_password','Current password','','password','required autocomplete="current-password"');field('new_password','New password','','password','required minlength="14" autocomplete="new-password"');field('confirm_password','Confirm new password','','password','required minlength="14" autocomplete="new-password"');echo '<button class="button primary">Change password</button></form>';}
function emails_view(): void {
    echo '<div class="admin-toolbar"><p>Transactional messages are queued after verified payment or fulfillment.</p><form method="post">'.csrf().'<input type="hidden" name="action" value="mail_run"><button class="button primary">Process queue now</button></form></div><div class="surface table-wrap"><table><thead><tr><th>Order / message</th><th>Recipient</th><th>Status</th><th>Attempts</th><th>Details</th></tr></thead><tbody>';
    $jobs=all('SELECT q.*,o.order_number FROM email_queue q JOIN orders o ON o.id=q.order_id ORDER BY q.id DESC LIMIT 100');foreach($jobs as $j){echo '<tr><td><a href="/admin/order?id='.$j['order_id'].'">'.e($j['order_number']).'</a><small>'.e(ucwords(str_replace('_',' ',$j['kind']))).'</small></td><td>'.e($j['recipient']).'</td><td>'.status_badge($j['status']).'</td><td>'.$j['attempts'].'</td><td>'.e($j['last_error']).'<small>'.e($j['sent_at']?when($j['sent_at']):'Next attempt: '.when($j['available_at'])).'</small>';if($j['status']!=='sent')action_form('mail_retry',(int)$j['id'],'Retry');echo '</td></tr>';}if(!$jobs)echo '<tr><td colspan="5">No email jobs yet. Messages will appear after a payment is confirmed.</td></tr>';echo '</tbody></table></div>';
}
function settings_view(): void {
    request_settings_view();
    global $config;echo '<form class="settings-form" method="post" enctype="multipart/form-data">'.csrf().'<input type="hidden" name="action" value="settings"><section class="surface"><h2>Brand & contact</h2><div class="form-grid"><div>';field('site_name','Site name',setting('site_name'));field('support_email','Support email',setting('support_email'),'email','required');field('support_phone','Support phone (optional)',setting('support_phone'));field('support_hours','Support hours (optional)',setting('support_hours'));echo '</div><div>';field('site_logo','Replace header logo (PNG, JPEG or WebP)','','file','accept="image/png,image/jpeg,image/webp"');area('business_address','Business address (optional)',setting('business_address'));echo '<div class="form-grid three">';foreach(['primary','secondary','accent'] as $c){echo '<div>';field('color_'.$c,ucfirst($c),setting('color_'.$c),'color');echo '</div>';}echo '</div></div></div></section><section class="surface"><h2>Homepage</h2>';field('hero_title','Headline, line 1',setting('hero_title'));field('hero_accent','Headline, line 2',setting('hero_accent'));area('hero_description','Introductory text',setting('hero_description'));echo '</section><section class="surface"><h2>Stripe payments</h2><div class="notice">Card details go directly to Stripe. Test and Live keys are stored separately. Secret fields are never displayed; leave them blank to keep their saved values.</div><label for="stripe_mode">Payment mode</label><select name="stripe_mode" id="stripe_mode"><option value="test" '.(stripe_mode()==='test'?'selected':'').'>Test</option><option value="live" '.(stripe_mode()==='live'?'selected':'').'>Live</option></select>';checkbox('checkout_enabled','Enable customer checkout',setting('checkout_enabled')==='1');echo '<p class="muted">Enable only after setting Stripe, SMTP, a webhook, verified plans, and confirming manual fulfillment is ready.</p><div class="form-grid">';foreach(['test','live'] as $mode){echo '<fieldset><legend>'.ucfirst($mode).' credentials</legend>';field('stripe_'.$mode.'_publishable','Publishable key',setting('stripe_'.$mode.'_publishable'));field('stripe_'.$mode.'_secret','Secret key'.(setting('stripe_'.$mode.'_secret')?' (saved)':''),'','password','autocomplete="new-password"');field('stripe_'.$mode.'_webhook','Webhook signing secret'.(setting('stripe_'.$mode.'_webhook')?' (saved)':''),'','password','autocomplete="new-password"');echo '</fieldset>';}echo '</div><p>Webhook URL: <code>'.e($config['base_url'].'/api/webhook').'</code></p><p class="muted">Subscribe to payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, payment_intent.processing, charge.refunded, refund.created, refund.updated and refund.failed.</p></section><section class="surface"><h2>SMTP email</h2><div class="form-grid"><div>';field('smtp_host','SMTP hostname',setting('smtp_host'));field('smtp_port','Port',setting('smtp_port','587'),'number','min="1" max="65535" required');echo '<label for="smtp_security">Encryption</label><select name="smtp_security" id="smtp_security"><option value="tls" '.(setting('smtp_security')==='tls'?'selected':'').'>STARTTLS (usually 587)</option><option value="ssl" '.(setting('smtp_security')==='ssl'?'selected':'').'>Implicit TLS (usually 465)</option></select></div><div>';field('smtp_username','Username',setting('smtp_username'));field('smtp_password','Password'.(setting('smtp_password')?' (saved)':''),'','password','autocomplete="new-password"');field('sender_email','Sender email',setting('sender_email','info@mitechwireless.com'),'email','required');echo '</div></div><p class="muted">Run tools/cron.php every five minutes so queued receipts and completion messages are delivered and retried.</p></section><section class="surface"><h2>Frequently asked questions</h2><p>Blank question-and-answer pairs are omitted. Use the empty rows to add questions.</p>';foreach([...faq_items(),...array_fill(0,3,['question'=>'','answer'=>''])] as $i=>$faq){echo '<fieldset><legend>Question '.($i+1).'</legend><label for="faq-q-'.$i.'">Question</label><input id="faq-q-'.$i.'" name="faq_question[]" maxlength="250" value="'.e($faq['question']).'"><label for="faq-a-'.$i.'">Answer</label><textarea id="faq-a-'.$i.'" name="faq_answer[]" maxlength="3000" rows="3">'.e($faq['answer']).'</textarea></fieldset>';}echo '</section><section class="surface"><h2>Extra footer links</h2>';area('footer_links','JSON array of {"label":"…","url":"/path"}',json_encode(json_decode(setting('footer_links','[]'),true),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),4);echo '</section><div class="settings-save"><button class="button primary">Save all settings</button></div></form><section class="surface"><h2>Send an SMTP test</h2><p>Save your SMTP configuration first, then send a test to an inbox you control.</p><form method="post" class="inline-filter">'.csrf().'<input type="hidden" name="action" value="smtp_test"><div>';field('test_email','Recipient email',setting('support_email'),'email','required');echo '</div><button class="button secondary">Send test email</button></form></section>';
}
